const bodyOf=x=>{if(typeof x==='string')return x;if(typeof x?.body==='string')return x.body;if(typeof x?.data==='string')return x.data;return '';};
const statusOf=x=>Number(x?.statusCode||x?.status||0)||null;
const hostname=u=>String(u||'').replace(/^https?:\/\//i,'').split('/')[0];
const attr=(tag,name)=>{const m=String(tag||'').match(new RegExp(name+'\\s*=\\s*[\"\\']([^\"\\']*)[\"\\']','i'));return m?m[1]:'';};
const htmlAudit=(html,domain)=>{html=String(html||'');const title=(html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();const metas=[...html.matchAll(/<meta\b[^>]*>/gi)].map(m=>m[0]);const links=[...html.matchAll(/<link\b[^>]*>/gi)].map(m=>m[0]);const descTag=metas.find(t=>/^description$/i.test(attr(t,'name')));const canonicalTag=links.find(t=>/\bcanonical\b/i.test(attr(t,'rel')));const h1=[...html.matchAll(/<h1\b[^>]*>([\s\S]*?)<\/h1>/gi)].map(m=>m[1].replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim());const imgs=[...html.matchAll(/<img\b[^>]*>/gi)].map(m=>m[0]);const anchors=[...html.matchAll(/<a\b[^>]*>/gi)].map(m=>attr(m[0],'href')).filter(Boolean);const internal=anchors.filter(h=>h.startsWith('/')||h.includes(domain));const schemaTypes=[...html.matchAll(/"@type"\s*:\s*"([^"]+)"/gi)].map(m=>m[1]);return{title,titleLength:title.length,metaDescription:attr(descTag,'content'),metaDescriptionLength:attr(descTag,'content').length,canonical:attr(canonicalTag,'href'),h1Count:h1.length,h1:h1.slice(0,5),schemaTypes:[...new Set(schemaTypes)],images:imgs.length,imagesMissingAlt:imgs.filter(t=>!/\balt\s*=/i.test(t)||attr(t,'alt').trim()==='').length,internalLinks:internal.length,linksTotal:anchors.length,htmlBytes:html.length};};
const robotsAudit=txt=>{txt=String(txt||'');return{bytes:txt.length,sitemapDirectives:[...txt.matchAll(/^\s*Sitemap:\s*(.+)$/gmi)].map(m=>m[1].trim()),disallow:[...txt.matchAll(/^\s*Disallow:\s*(.*)$/gmi)].map(m=>m[1].trim()).filter(Boolean).slice(0,100),blocksAll:/User-agent:\s*\*[\s\S]{0,300}Disallow:\s*\/\s*$/mi.test(txt)};};
const sitemapAudit=xml=>{xml=String(xml||'');const locs=[...xml.matchAll(/<loc>\s*([\s\S]*?)\s*<\/loc>/gi)].map(m=>String(m[1]).trim());const isIndex=/<sitemapindex\b/i.test(xml);return{bytes:xml.length,type:isIndex?'sitemapindex':(/<urlset\b/i.test(xml)?'urlset':'unknown'),locCount:locs.length,locs:locs.slice(0,500)};};
const sumPerf=rows=>{rows=Array.isArray(rows)?rows:[];const clicks=rows.reduce((a,r)=>a+Number(r.clicks||0),0);const impressions=rows.reduce((a,r)=>a+Number(r.impressions||0),0);const ctr=impressions?clicks/impressions:0;const posN=rows.reduce((a,r)=>a+Number(r.position||0)*Number(r.impressions||0),0);return{clicks,impressions,ctrPercent:Number((ctr*100).toFixed(2)),avgPosition:Number((impressions?posN/impressions:0).toFixed(2)),days:rows.length};};
const result=sites.map((s,i)=>{const idx=ins[i]?.inspectionResult?.indexStatusResult||{};const psiItem=psi[i]||{};const cats=psiItem?.lighthouseResult?.categories||{};const audits=psiItem?.lighthouseResult?.audits||{};const metric=k=>({display:audits[k]?.displayValue??null,value:audits[k]?.numericValue??null});const psiQuota=Number(psiItem?.error?.code||0)===429||/quota|rate.?limit/i.test(String(psiItem?.error?.message||psiItem?.message||''));return{site:s.name,url:s.publicUrl,gsc:sumPerf(perf[i]?.rows),topQueriesAndPages:(top[i]?.rows||[]).slice(0,50),sitemaps:maps[i]?.sitemap||[],inspection:{verdict:idx.verdict||null,coverageState:idx.coverageState||null,robotsTxtState:idx.robotsTxtState||null,indexingState:idx.indexingState||null,pageFetchState:idx.pageFetchState||null,lastCrawlTime:idx.lastCrawlTime||null,googleCanonical:idx.googleCanonical||null,userCanonical:idx.userCanonical||null},live:{homeStatus:statusOf(home[i]),robotsStatus:statusOf(robots[i]),sitemapStatus:statusOf(sm[i]),home:htmlAudit(bodyOf(home[i]),hostname(s.publicUrl)),robots:robotsAudit(bodyOf(robots[i])),sitemap:sitemapAudit(bodyOf(sm[i]))},pagespeed:psiQuota?{status:'quota_exceeded',code:429}:{status:psiItem?.lighthouseResult?'ok':'unavailable',performance:cats.performance?.score==null?null:Math.round(cats.performance.score*100),seo:cats.seo?.score==null?null:Math.round(cats.seo.score*100),accessibility:cats.accessibility?.score==null?null:Math.round(cats.accessibility.score*100),metrics:{fcp:metric('first-contentful-paint'),lcp:metric('largest-contentful-paint'),cls:metric('cumulative-layout-shift'),tbt:metric('total-blocking-time')}}};});
